-- AiGIS seed data. Generated by scripts/generate-seed.mjs: edit that, not this file.
--
-- Resets stock, orders and forecasts to a realistic history for the existing
-- items, from 2026-04-13 to 2026-10-10. Running it again gives the same data.
--
-- REMOVES every row from: ai_forecasts, demand_forecasts, news_verdicts,
-- articles, llm_calls, council_seats, council_runs, sync_runs, purchase_orders,
-- po_documents, batches, daily_inventory, weekly_inventory, haze_api_weekly.
-- KEEPS: news sources, policies, and suppliers.email.
--
-- After running it, press Full sync on the Predictions page for fresh forecasts.

BEGIN;

TRUNCATE TABLE public.ai_forecasts, public.demand_forecasts, public.news_verdicts, public.articles, public.llm_calls, public.council_seats, public.council_runs, public.sync_runs, public.purchase_orders, public.po_documents, public.batches, public.daily_inventory, public.weekly_inventory, public.haze_api_weekly RESTART IDENTITY;

ON CONFLICT (facility_id) DO UPDATE SET facility_name = EXCLUDED.facility_name, facility_type = EXCLUDED.facility_type, sector = EXCLUDED.sector, district = EXCLUDED.district, state = EXCLUDED.state, size_tier = EXCLUDED.size_tier;

ON CONFLICT (supplier_id) DO UPDATE SET supplier_name = EXCLUDED.supplier_name, supplier_type = EXCLUDED.supplier_type, state = EXCLUDED.state, lead_time_days = EXCLUDED.lead_time_days, reliability_score = EXCLUDED.reliability_score, country = EXCLUDED.country;

ON CONFLICT (item_id) DO UPDATE SET item_name = EXCLUDED.item_name, category = EXCLUDED.category, unit = EXCLUDED.unit, unit_cost_myr = EXCLUDED.unit_cost_myr, shelf_life_months = EXCLUDED.shelf_life_months, is_critical = EXCLUDED.is_critical, storage = EXCLUDED.storage, primary_supplier_id = EXCLUDED.primary_supplier_id, cover_days = COALESCE(items.cover_days, EXCLUDED.cover_days), reorder_level = COALESCE(items.reorder_level, EXCLUDED.reorder_level);













COMMIT;
